<?php
require_once __DIR__ . '/inc/connect.php';
require_once __DIR__ . '/inc/auth.php';
if (!in_array((int)($_SESSION['log_role'] ?? 0), [1,2,4], true)) { http_response_code(403); exit('Not authorized.'); }
$role=(int)$_SESSION['log_role'];$userId=(int)$_SESSION['u_id'];$notice='';$error='';
$isReviewer=in_array($role,[2,4],true);

if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        $action=(string)($_POST['action']??'');
        if($action==='import_dataset'){
            if(!in_array($role,[1,2,4],true))throw new RuntimeException('Not authorized to import datasets.');
            $name=trim((string)($_POST['dataset_name']??''));$version=trim((string)($_POST['dataset_version']??''));$purpose=trim((string)($_POST['purpose']??'intent_classification'));
            if($name===''||$version===''||!preg_match('/^[a-zA-Z0-9._-]{1,50}$/',$version))throw new RuntimeException('Provide a dataset name and a version using letters, numbers, dots, underscores or hyphens.');
            if(!isset($_FILES['jsonl'])||$_FILES['jsonl']['error']!==UPLOAD_ERR_OK||$_FILES['jsonl']['size']>10*1024*1024)throw new RuntimeException('Choose a JSONL file under 10 MB.');
            $raw=file_get_contents($_FILES['jsonl']['tmp_name']);if(!is_string($raw)||$raw==='')throw new RuntimeException('The uploaded file is empty.');
            $lines=preg_split('/\r\n|\n|\r/',$raw);if(count($lines)>5001)throw new RuntimeException('A dataset upload may contain up to 5,000 examples.');
            $rows=[];$groups=[];
            foreach($lines as $n=>$line){if(trim($line)==='')continue;$item=json_decode($line,true);if(!is_array($item))throw new RuntimeException('Invalid JSON on line '.($n+1).'.');
                $text=trim((string)($item['text']??''));$lang=(string)($item['language']??'');$intent=trim((string)($item['intent']??''));$group=trim((string)($item['source_group']??''));
                if($text===''||mb_strlen($text,'UTF-8')>5000||!in_array($lang,['en','rw'],true)||$intent===''||mb_strlen($intent)>80||$group==='')throw new RuntimeException('Each row needs text (max 5,000 chars), language en/rw, intent label and an anonymized source_group. Error on line '.($n+1).'.');
                if(preg_match('/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i',$text)||preg_match('/(?<!\d)(?:\+?\d[\d .()\-]{8,}\d)(?!\d)/',$text))throw new RuntimeException('Possible email address or phone number found on line '.($n+1).'. Remove identifying information before upload.');
                $groupHash=hash('sha256',$group);$bucket=hexdec(substr($groupHash,0,8))%100;$split=$bucket<80?'train':($bucket<90?'validation':'test');$groups[$groupHash]=$split;
                $annotations=is_array($item['annotations']??null)?$item['annotations']:[];$annotations['intent']=$intent;
                $rows[]=['text'=>$text,'language'=>$lang,'intent'=>$intent,'group_hash'=>$groupHash,'split'=>$split,'annotations'=>json_encode($annotations,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),'expected'=>isset($item['expected_output'])?mb_substr((string)$item['expected_output'],0,5000,'UTF-8'):null];
            }
            if(!$rows)throw new RuntimeException('No examples were found.');
            $db->beginTransaction();
            $insert=$db->prepare("INSERT INTO tbl_ai_datasets(dataset_name,dataset_version,language_scope,purpose,status,source_description,deidentification_method,consent_basis,created_by) VALUES(?,?,'en,rw',?,'review',?,?,?,?)");
            $insert->execute([$name,$version,$purpose,trim((string)($_POST['source_description']??''))?:null,'Uploader attests examples are de-identified; source groups are hashed before storage.',trim((string)($_POST['consent_basis']??''))?:null,$userId]);$datasetId=(int)$db->lastInsertId();
            $save=$db->prepare("INSERT INTO tbl_ai_dataset_examples(dataset_id,split_name,language,input_text,expected_output,annotations,source_digest,quality_status) VALUES(?,?,?,?,?,?,?,'pending')");
            foreach($rows as $row)$save->execute([$datasetId,$row['split'],$row['language'],$row['text'],$row['expected'],$row['annotations'],hash('sha256',$datasetId.':'.$row['group_hash'])]);
            $db->commit();$notice='Dataset imported for professional review. It is not available for training yet.';
        }elseif($action==='review_example'){
            if(!$isReviewer)throw new RuntimeException('Only clinical professionals may review dataset examples.');
            $exampleId=(int)($_POST['example_id']??0);$decision=(string)($_POST['decision']??'');if(!in_array($decision,['approved','rejected'],true))throw new RuntimeException('Invalid review decision.');
            $check=$db->prepare("SELECT e.dataset_id,d.created_by FROM tbl_ai_dataset_examples e JOIN tbl_ai_datasets d ON d.dataset_id=e.dataset_id WHERE e.example_id=?");$check->execute([$exampleId]);$owner=$check->fetch(PDO::FETCH_ASSOC);if(!$owner)throw new RuntimeException('Example not found.');if((int)$owner['created_by']===$userId)throw new RuntimeException('A different clinical professional must review your uploaded dataset.');
            $db->prepare("UPDATE tbl_ai_dataset_examples SET quality_status=?,reviewed_by=?,reviewed_at=NOW() WHERE example_id=? AND quality_status='pending'")->execute([$decision,$userId,$exampleId]);$notice='Example review saved.';
        }elseif($action==='approve_dataset'){
            if(!$isReviewer)throw new RuntimeException('Only a clinical professional may approve a dataset.');
            $datasetId=(int)($_POST['dataset_id']??0);$check=$db->prepare("SELECT created_by FROM tbl_ai_datasets WHERE dataset_id=? AND status='review'");$check->execute([$datasetId]);$owner=$check->fetchColumn();if(!$owner)throw new RuntimeException('Dataset not found or not awaiting review.');if((int)$owner===$userId)throw new RuntimeException('A different clinical professional must approve this dataset.');
            $pending=$db->prepare("SELECT COUNT(*) FROM tbl_ai_dataset_examples WHERE dataset_id=? AND quality_status<>'approved'");$pending->execute([$datasetId]);if((int)$pending->fetchColumn()>0)throw new RuntimeException('Review and approve every example before approving this dataset.');
            $db->prepare("UPDATE tbl_ai_datasets SET status='approved',approved_by=?,approved_at=NOW() WHERE dataset_id=?")->execute([$userId,$datasetId]);$notice='Dataset approved for controlled training.';
        }elseif($action==='queue_training'){
            if($role!==1)throw new RuntimeException('Only administrators may start training jobs.');
            $datasetId=(int)($_POST['dataset_id']??0);$check=$db->prepare("SELECT COUNT(*) FROM tbl_ai_datasets WHERE dataset_id=? AND status='approved'");$check->execute([$datasetId]);if(!(int)$check->fetchColumn())throw new RuntimeException('Choose a professionally approved dataset.');
            $db->prepare("INSERT INTO tbl_ai_training_jobs(dataset_id,job_type,status,configuration,requested_by) VALUES(?,'classifier_training','queued',?,?)")->execute([$datasetId,json_encode(['component'=>'bilingual_intent_classifier','algorithm'=>'char_tfidf_logistic_regression'],JSON_UNESCAPED_UNICODE),$userId]);$notice='Training job queued. Run the worker command shown below on the private application server.';
        }else throw new RuntimeException('Unknown action.');
    }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}
}
$datasets=$db->query("SELECT d.*,(SELECT COUNT(*) FROM tbl_ai_dataset_examples e WHERE e.dataset_id=d.dataset_id) example_count,(SELECT COUNT(*) FROM tbl_ai_dataset_examples e WHERE e.dataset_id=d.dataset_id AND e.quality_status='pending') pending_count FROM tbl_ai_datasets d ORDER BY d.created_at DESC LIMIT 50")->fetchAll(PDO::FETCH_ASSOC);
$pendingExamples=$db->query("SELECT e.*,d.dataset_name,d.dataset_version FROM tbl_ai_dataset_examples e JOIN tbl_ai_datasets d ON d.dataset_id=e.dataset_id WHERE e.quality_status='pending' AND d.status='review' ORDER BY e.created_at LIMIT 50")->fetchAll(PDO::FETCH_ASSOC);
$jobs=$db->query("SELECT j.*,d.dataset_name,m.model_name,m.version model_version FROM tbl_ai_training_jobs j JOIN tbl_ai_datasets d ON d.dataset_id=j.dataset_id LEFT JOIN tbl_ai_model_versions m ON m.model_id=j.output_model_id ORDER BY j.created_at DESC LIMIT 25")->fetchAll(PDO::FETCH_ASSOC);
$approved=array_values(array_filter($datasets,static fn($d)=>$d['status']==='approved'));
$page_title='AI training governance';include 'inc/links.php';include 'inc/header.php';
?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php'; ?><section role="main" class="content-body"><?php include 'inc/inner-header.php'; ?>
<section class="panel"><header class="panel-heading"><h2 class="panel-title">M-CARE AI training and review</h2></header><div class="panel-body">
<div class="alert alert-warning"><strong>Clinical governance:</strong> Chat messages are never automatically used for training. Upload only authorized, de-identified examples. Datasets require independent clinical review; trained models remain in development until separately evaluated and approved. The current trainer learns intent labels only, not diagnoses or treatment.</div>
<?php if($notice): ?><div class="alert alert-success"><?=htmlspecialchars($notice)?></div><?php endif; ?><?php if($error): ?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif; ?>
<?php if(in_array($role,[1,2,4],true)): ?><h3>Import de-identified JSONL dataset</h3><p>One JSON object per line: <code>{"text":"...","language":"rw","intent":"symptom","source_group":"anonymous-conversation-17"}</code>. Examples from the same source group stay in one deterministic train/validation/test split. Do not include names, contact details, IDs, or unconsented chat transcripts.</p>
<form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="import_dataset"><div class="row"><div class="col-md-4"><label>Dataset name</label><input class="form-control" name="dataset_name" required maxlength="180"></div><div class="col-md-2"><label>Version</label><input class="form-control" name="dataset_version" required placeholder="v1.0"></div><div class="col-md-3"><label>Source summary</label><input class="form-control" name="source_description" maxlength="500"></div><div class="col-md-3"><label>Consent / authorization basis</label><input class="form-control" name="consent_basis" maxlength="500" required></div></div><div class="form-group" style="margin-top:12px"><label>JSONL file (max 10 MB)</label><input type="file" name="jsonl" accept=".jsonl,.txt,application/json" required></div><button class="btn btn-primary">Import for review</button></form><?php endif; ?>
<hr><h3>Datasets</h3><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Dataset</th><th>Status</th><th>Examples</th><th>Created</th><th>Action</th></tr></thead><tbody><?php foreach($datasets as $d): ?><tr><td><?=htmlspecialchars($d['dataset_name'].' · '.$d['dataset_version'])?></td><td><?=htmlspecialchars($d['status'])?></td><td><?=(int)$d['example_count']?> (<?=(int)$d['pending_count']?> pending)</td><td><?=htmlspecialchars($d['created_at'])?></td><td><?php if($isReviewer&&$d['status']==='review'&&(int)$d['created_by']!==$userId&&(int)$d['pending_count']===0): ?><form method="post"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="approve_dataset"><input type="hidden" name="dataset_id" value="<?=(int)$d['dataset_id']?>"><button class="btn btn-success btn-xs">Approve dataset</button></form><?php elseif($role===1&&$d['status']==='approved'): ?><form method="post"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="queue_training"><input type="hidden" name="dataset_id" value="<?=(int)$d['dataset_id']?>"><button class="btn btn-primary btn-xs">Queue intent training</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if($isReviewer): ?><h3>Examples awaiting clinical review</h3><?php foreach($pendingExamples as $ex): ?><div class="panel panel-default"><div class="panel-body"><small><?=htmlspecialchars($ex['dataset_name'].' · '.$ex['split_name'].' · '.$ex['language'])?></small><p><?=nl2br(htmlspecialchars($ex['input_text']))?></p><pre><?=htmlspecialchars((string)$ex['annotations'])?></pre><form method="post"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="review_example"><input type="hidden" name="example_id" value="<?=(int)$ex['example_id']?>"><button name="decision" value="approved" class="btn btn-success btn-xs">Approve example</button> <button name="decision" value="rejected" class="btn btn-danger btn-xs">Reject example</button></form></div></div><?php endforeach; ?><?php endif; ?>
<h3>Training jobs and evaluated versions</h3><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Job</th><th>Dataset</th><th>Status</th><th>Model version</th><th>Created</th></tr></thead><tbody><?php foreach($jobs as $j): ?><tr><td>#<?=(int)$j['job_id']?> · <?=htmlspecialchars($j['job_type'])?></td><td><?=htmlspecialchars($j['dataset_name'])?></td><td><?=htmlspecialchars($j['status'])?></td><td><?=htmlspecialchars(trim((string)$j['model_name'].' '.(string)$j['model_version']))?></td><td><?=htmlspecialchars($j['created_at'])?></td></tr><?php endforeach; ?></tbody></table></div>
<p>Run queued offline jobs from the application server with <code>python3 ai_service/train_intent.py --job-id JOB_ID</code>. Set <code>MCARE_DB_HOST</code>, <code>MCARE_DB_USER</code>, <code>MCARE_DB_PASSWORD</code>, <code>MCARE_DB_NAME</code>, and <code>MCARE_MODEL_DIR</code> for the worker. A successful model is recorded as development and is not activated for clinical decisions.</p>
</div></section></section></div><?php include 'inc/footer.php';include 'inc/scripts.php'; ?>
